# This file defines conventions for where SegTraQ stores its results in the AnnData object.
# This is to avoid conflicts with other tools and to make it clear which data is generated by SegTraQ.

# ── Layers ────────────────────────────────────────────────────────────────────
NORM_LOG_LAYER = "norm_log_segtraq"

# ── Highly variable genes ─────────────────────────────────────────────────────
HVG_KEY = "highly_variable_segtraq"
HVG_PANEL_SIZE_THRESHOLD = 8_000

# ── Obsm ──────────────────────────────────────────────────────────────────────
PCA_KEY = "X_pca_segtraq"

# ── Uns ───────────────────────────────────────────────────────────────────────
NEIGHBORS_KEY = "neighbors_segtraq"

# ── Obsp ──────────────────────────────────────────────────────────────────────
CONNECTIVITIES_KEY = f"{NEIGHBORS_KEY}_connectivities"
DISTANCES_KEY = f"{NEIGHBORS_KEY}_distances"

# ── Cell ID ───────────────────────────────────────────────────────────────────
SEGTRAQ_CELL_ID_KEY = "segtraq_id"

# ── Control probes and low quality transcripts ────────────────────────────────
DEFAULT_FILTER_KWARGS = {
    "min_qv": 20,
    "control_prefixes": (
        "NegControlProbe_",
        "antisense_",
        "NegControlCodeword",
        "BLANK_",
        "Blank-",
        "NegPrb",
        "DeprecatedCodeword_",
        "UnassignedCodeword_",
        "Intergenic_Region_",
    ),
    "inplace": True,
}

# ── Mitochondrial and ribosomal gene filtering ────────────────────────────────
DEFAULT_EXCLUDE_GENE_PREFIXES = ("MT-", "RPL", "RPS")

# Reference arguments that wrappers pass explicitly to `run_label_transfer` / module runners.
_REFERENCE_KWARGS = frozenset({"adata_ref", "ref_cell_type", "ref_gene_key", "query_gene_key", "ref_raw_counts_layer"})
